use tapecpy::{app, device::lease};
fn main() -> Result<(), String> {
 let target = std::env::args().nth(1).ok_or("target required")?;
 let drives = app::discover_drives().map_err(|e| e.to_string())?;
 let drive = app::select_drive(&drives, Some("/dev/sg0"))?;
 let _lock = lease::DeviceLease::try_acquire(&drive.serial, lease::LeaseOwner::new("hardware-test", "temperature-ab"))?;
 let start = std::time::Instant::now();
 let mut observer = |e: &app::WriteEvent| {
   if let Some(p) = &e.performance { println!("{}", serde_json::json!({"kind":"performance","elapsed":start.elapsed().as_secs_f64(),"bytes":e.bytes_written,"tape_bps":p.tape_bytes_per_second,"source_bps":p.source_bytes_per_second,"buffer":p.buffer_used_bytes,"capacity":p.buffer_capacity_bytes,"reader_waiting":p.reader_waiting,"writer_waiting":p.writer_waiting})); }
   if let Some(t) = &e.telemetry { println!("{}", serde_json::json!({"kind":"telemetry","elapsed":start.elapsed().as_secs_f64(),"bytes":e.bytes_written,"temperature":t.temperature,"worst_rate":t.worst_rate})); }
   if e.performance.is_none() && e.telemetry.is_none() { println!("{}", serde_json::json!({"kind":"phase","phase":format!("{:?}",e.phase),"elapsed":start.elapsed().as_secs_f64(),"bytes":e.bytes_written})); }
 };
 let result = app::WriteSession::new(drive).run_pseudorandom(4*1024*1024*1024, 12345, &target, app::WriteOptions::default(), &mut observer)?;
 println!("{}",serde_json::json!({"kind":"complete","elapsed":start.elapsed().as_secs_f64(),"result":format!("{result:?}")}));
 Ok(())
}
